package com.finance.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDate; import java.time.Instant;
@Document("transactions")
public class Transaction {
 @Id private String id; private String userId; private String type; private String category; private String description; private long amountPaise; private LocalDate date; private String paymentMethod; private boolean recurring; private String recurringSourceId; private LocalDate recurringOccurrenceDate; private Instant createdAt=Instant.now();
 public String getId(){return id;} public void setId(String v){id=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public long getAmountPaise(){return amountPaise;} public void setAmountPaise(long v){amountPaise=v;} public LocalDate getDate(){return date;} public void setDate(LocalDate v){date=v;} public String getPaymentMethod(){return paymentMethod;} public void setPaymentMethod(String v){paymentMethod=v;} public boolean isRecurring(){return recurring;} public void setRecurring(boolean v){recurring=v;} public String getRecurringSourceId(){return recurringSourceId;} public void setRecurringSourceId(String v){recurringSourceId=v;} public LocalDate getRecurringOccurrenceDate(){return recurringOccurrenceDate;} public void setRecurringOccurrenceDate(LocalDate v){recurringOccurrenceDate=v;} public Instant getCreatedAt(){return createdAt;}
}
